SELECT 
FROM learning_raw_candidate
WHERE user_id = #{userId}
  AND candidate_type = #{candidateType}
  AND normalized_text = #{normalizedText}
  AND extractor_type = #{extractorType}
LIMIT 1

SELECT 
FROM learning_raw_candidate
WHERE message_uid = #{messageUid}
  AND extractor_type = #{extractorType}
ORDER BY final_candidate_score DESC, id DESC

SELECT 
FROM learning_raw_candidate
WHERE user_id = #{userId}
  AND last_seen_at >= #{from}
  AND last_seen_at < #{to}
ORDER BY final_candidate_score DESC, occurrence_count DESC, last_seen_at DESC
